# IMAGEN CARILO EMBEBIDA BASE64 - V126 EMBEDDED
CARILO_IMG_BASE64 = """"""
# Full string split to avoid huge line - we will reconstruct
CARILO_IMG_BASE64_FULL = """"""

CARPETA_BACKUP="backups_panol"
os.makedirs(CARPETA_BACKUP, exist_ok=True)

def hacer_backup(motivo="MANUAL"):
    """
    Backup profesional:
    - Usa API oficial sqlite3.backup() (no copia archivo en caliente corrupto)
    - Nombre limpio: panol_YYYYMMDD_HHMMSS_MOTIVO.db (una sola fecha)
    - Verifica con hash y guarda solo ultimos 10
    """
    try:
        CARPETA_BACKUP.mkdir(parents=True, exist_ok=True)
        fecha = datetime.now().strftime("%Y%m%d_%H%M%S")
        # Nombre profesional: fecha primero para ordenar facil
        dest = CARPETA_BACKUP / f"panol_{fecha}_{motivo}.db"

        # Copia atomica con API SQLite (profesional)
        src_conn = sqlite3.connect(str(DB_PATH), timeout=15)
        dst_conn = sqlite3.connect(str(dest), timeout=15)
        src_conn.backup(dst_conn)
        dst_conn.close()
        src_conn.close()

        # Verificacion rapida con MD5 (8 chars)
        md5 = hashlib.md5(dest.read_bytes()).hexdigest()[:8]

        # Retencion: guarda solo los ultimos 10 backups
        todos = sorted(CARPETA_BACKUP.glob("panol_*.db"), key=lambda p: p.stat().st_mtime, reverse=True)
        for viejo in todos[10:]:
            try:
                viejo.unlink()
            except:
                pass

        print(f"[BACKUP OK] {dest} md5:{md5} - quedan {min(len(todos),10)} backups")
        return True, str(dest)
    except Exception as e:
        print(f"[BACKUP ERROR] {e}")
        return False, str(e)

def restaurar_backup(ruta_backup: str):
    """Restaura un backup de forma segura (profesional)"""
    try:
        ruta = Path(ruta_backup)
        if not ruta.exists():
            return False, "Archivo no existe"
        # Backup de seguridad del actual antes de restaurar
        hacer_backup("PRE_RESTAURAR")
        # Restaurar usando backup API inverso
        src_conn = sqlite3.connect(str(ruta))
        dst_conn = sqlite3.connect(str(DB_PATH))
        src_conn.backup(dst_conn)
        dst_conn.close()
        src_conn.close()
        return True, str(ruta)
    except Exception as e:
        return False, str(e)

def init_db():
    conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
    cur.execute("""CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT UNIQUE, password TEXT, contrasena TEXT, rol TEXT)""")
    try:
        cur.execute("SELECT contrasena FROM usuarios LIMIT 1")
    except:
        try: cur.execute("ALTER TABLE usuarios ADD COLUMN contrasena TEXT")
        except: pass
    cur.execute("SELECT COUNT(*) FROM usuarios")
    if cur.fetchone()[0]==0:
        cur.execute("INSERT INTO usuarios (nombre,password,contrasena,rol) VALUES (?,?,?,?)",("Ariel Perea","admin123","admin123","administrador master"))
    cur.execute("""CREATE TABLE IF NOT EXISTS materiales (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT, stock INTEGER, marca TEXT, proveedor TEXT, minimo INTEGER, ubicacion TEXT, fecha TEXT, usa_minimo INTEGER DEFAULT 1, foto TEXT)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS movimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, material_id INTEGER, material_nombre TEXT, usuario TEXT, cantidad INTEGER, tipo TEXT, fecha TEXT, destino TEXT, motivo TEXT, stock_final INTEGER)""")
    cur.execute("CREATE TABLE IF NOT EXISTS config (clave TEXT PRIMARY KEY, valor TEXT)")
    conn.commit(); conn.close()

init_db()

