        ctk.CTkLabel(header, text=f"OTEADOR - {self.usuario['nombre']} ({self.usuario['rol']})", font=("Arial",14,"bold")).pack(side="left", padx=15)
        # Label de usuario activo
        self.lbl_activo = ctk.CTkLabel(header, text=f"ACTIVO: {self.usuario['nombre']}", font=("Arial",10,"bold"), text_color="#C62828")
        self.lbl_activo.pack(side="left", padx=20)
        ctk.CTkButton(header, text="Cerrar sesión", width=110, fg_color="gray", command=self.mostrar_login).pack(side="right", padx=5)
        # AUTO-LOGOUT 2 HORAS SIN MOVIMIENTO
        self.ultimo_movimiento = datetime.now()
        def actualizar_movimiento(event=None):
            self.ultimo_movimiento = datetime.now()
        self.bind_all("<Motion>", actualizar_movimiento)
        self.bind_all("<Key>", actualizar_movimiento)
        self.bind_all("<Button-1>", actualizar_movimiento)
        def chequear_inactividad():
            try:
                if hasattr(self, 'ultimo_movimiento'):
                    diff = (datetime.now() - self.ultimo_movimiento).total_seconds()
                    if diff > 7200:  # 2 horas = 7200 seg
                        messagebox.showwarning("Sesión expirada", f"2 horas sin movimientos - Se cierra sesión de {self.usuario['nombre']} por seguridad - Debe loguearse otro usuario")
                        self.borrar_lock()
                        self.mostrar_login()
                        return
                    # Mostrar tiempo restante en titulo?
                    mins_rest = int((7200 - diff)/60)
                    if hasattr(self, 'lbl_activo'):
                        if mins_rest < 15:
                            self.lbl_activo.configure(text=f"ACTIVO: {self.usuario['nombre']} - Cierra en {mins_rest}min")
                self.after(60000, chequear_inactividad)  # chequear cada 1 min
            except:
                pass
        self.after(60000, chequear_inactividad)
        nav=ctk.CTkFrame(self, height=55); nav.pack(fill="x", padx=10, pady=5); nav.pack_propagate(False)
        rol_lower = self.usuario["rol"].lower()
        es_operario = "operario" in rol_lower or "pañolero" in rol_lower
        es_supervisor = "supervisor" in rol_lower
        es_admin = "administrador" in rol_lower or "master" in rol_lower
