    def mostrar_panel_retiro(self, mat_id, mat_nom, stock_actual, nombre_completo):
        for w in self.contenedor.winfo_children(): w.destroy()
        frame=ctk.CTkFrame(self.contenedor, fg_color="#FFF3E0", border_width=2, border_color="#FF9800"); frame.pack(fill="x", padx=80, pady=20)
        ctk.CTkLabel(frame, text="RETIRAR MATERIAL", font=("Arial",16,"bold"), text_color="#BF360C").pack(pady=10)
        ctk.CTkLabel(frame, text=f"{mat_nom} | Stock actual: {stock_actual}", font=("Arial",12,"bold")).pack(pady=5)
        ctk.CTkLabel(frame, text="CANTIDAD *", font=("Arial",11,"bold")).pack(anchor="w", padx=20, pady=(10,2))
        entry_cant=ctk.CTkEntry(frame, width=400); entry_cant.pack(padx=20, pady=5); entry_cant.insert(0,"1")
        ctk.CTkLabel(frame, text="DESTINO * obligatorio:", font=("Arial",11,"bold"), text_color="red").pack(anchor="w", padx=20, pady=(10,2))
        combo_dest=ctk.CTkComboBox(frame, values=["Taller","Producción","Mantenimiento","Obra","Otro"], width=400); combo_dest.pack(padx=20, pady=5); combo_dest.set("Taller")
        entry_dest_otro=ctk.CTkEntry(frame, placeholder_text="Si es Otro, escribir destino", width=400); entry_dest_otro.pack(padx=20, pady=5)
        ctk.CTkLabel(frame, text="MOTIVO * obligatorio:", font=("Arial",11,"bold"), text_color="red").pack(anchor="w", padx=20, pady=(10,2))
        combo_motivo=ctk.CTkComboBox(frame, values=["Uso en máquina","Consumo","Reparación","Instalación","Otro"], width=400); combo_motivo.pack(padx=20, pady=5); combo_motivo.set("Uso en máquina")
        entry_motivo_det=ctk.CTkEntry(frame, placeholder_text="Detalle del motivo (opcional)", width=400); entry_motivo_det.pack(padx=20, pady=5)
        def confirmar():
            try:
                cant=int(entry_cant.get().strip())
                destino_sel=combo_dest.get(); destino_otro=entry_dest_otro.get().strip()
                destino=destino_otro if destino_otro else destino_sel
                motivo_sel=combo_motivo.get(); motivo_det=entry_motivo_det.get().strip()
                motivo=f"{motivo_sel} - {motivo_det}" if motivo_det else motivo_sel
                if cant<=0 or cant>int(stock_actual):
                    messagebox.showerror("Error", f"Cantidad invalida. Stock {stock_actual}"); return
                nuevo=int(stock_actual)-cant
                conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
                cur.execute("CREATE TABLE IF NOT EXISTS movimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, material_id INTEGER, material_nombre TEXT, usuario TEXT, cantidad INTEGER, tipo TEXT, fecha TEXT, destino TEXT, motivo TEXT, stock_final INTEGER)")
                cur.execute("UPDATE materiales SET stock=? WHERE id=?",(nuevo, mat_id))
                cur.execute("INSERT INTO movimientos (material_id,material_nombre,usuario,cantidad,tipo,fecha,destino,motivo,stock_final) VALUES (?,?,?,?,?,?,?,?,?)",(mat_id, mat_nom, self.usuario["nombre"], cant, "RETIRO", datetime.now().strftime("%d/%m/%Y %H:%M"), destino, motivo, nuevo))
                conn.commit()
                cur.execute("SELECT COUNT(*) FROM movimientos")
                total=cur.fetchone()[0]
                conn.close()
                messagebox.showinfo("Retiro OK", f"Retiraste {cant} de {mat_nom}\nStock nuevo: {nuevo}\nTotal historial: {total}")
                self.cambiar_vista("Inventario")
            except Exception as e:
                messagebox.showerror("Error Retiro", str(e))
        btn_frame=ctk.CTkFrame(frame, fg_color="transparent"); btn_frame.pack(pady=15)
        ctk.CTkButton(btn_frame, text="Confirmar Retiro", fg_color="#C62828", width=180, height=40, command=confirmar).pack(side="left", padx=10)
        ctk.CTkButton(btn_frame, text="Cancelar", fg_color="gray", width=120, height=40, command=lambda: self.cambiar_vista("Inventario")).pack(side="left", padx=10)

