    def vista_retirados(self):
        for w in self.contenedor.winfo_children(): w.destroy()
        wrapper=ctk.CTkFrame(self.contenedor, fg_color="transparent"); wrapper.pack(fill="both", expand=True, padx=10, pady=10)
        ctk.CTkLabel(wrapper, text="HISTORIAL COMPLETO DE MOVIMIENTOS", font=("Arial",16,"bold")).pack(pady=10)
        rol_hist = self.usuario["rol"].lower()
        es_supervisor_hist = "supervisor" in rol_hist
        es_admin_hist = "administrador" in rol_hist or "master" in rol_hist
        es_operario_hist = "operario" in rol_hist or "pañolero" in rol_hist
        if es_supervisor_hist:
            combo_values = ["TODOS","INGRESO","INGRESO NUEVO","RETIRO","DEVOLUCION"]
        else:
            combo_values = ["TODOS","INGRESO","INGRESO NUEVO","RETIRO","DEVOLUCION","ALTA USUARIO","BAJA USUARIO"]
        top=ctk.CTkFrame(wrapper, fg_color="#E3F2FD", corner_radius=10); top.pack(fill="x", pady=5)
        ctk.CTkLabel(top, text="Buscar:", font=("Arial",11,"bold")).pack(side="left", padx=10, pady=8)
        e_bus=ctk.CTkEntry(top, placeholder_text="material, usuario, tipo...", width=250); e_bus.pack(side="left", padx=5, pady=8)
        combo_tipo=ctk.CTkComboBox(top, values=combo_values, width=170); combo_tipo.pack(side="left", padx=10); combo_tipo.set("TODOS")
        ctk.CTkButton(top, text="Buscar / Filtrar", fg_color="#1565C0", width=110, command=lambda: self.cargar_historial()).pack(side="left", padx=10)
        accion_frame=ctk.CTkFrame(wrapper, fg_color="transparent"); accion_frame.pack(fill="x", pady=5)
        self.frame_hist_lista=ctk.CTkScrollableFrame(wrapper, height=500); self.frame_hist_lista.pack(fill="both", expand=True, pady=10)
        self.historial_vars={}
        self.historial_combo_tipo=combo_tipo
        self.historial_bus=e_bus
        self.historial_es_supervisor=es_supervisor_hist
        # Botones sin bocina
        if es_supervisor_hist:
            ctk.CTkButton(accion_frame, text="Seleccionar Todo", fg_color="#616161", width=130, command=self.hist_seleccionar_todo).pack(side="left", padx=5)
            ctk.CTkButton(accion_frame, text="Deseleccionar Todo", fg_color="#9E9E9E", width=140, command=self.hist_deseleccionar_todo).pack(side="left", padx=5)
        else:
            ctk.CTkButton(accion_frame, text="Seleccionar Todo", fg_color="#616161", width=130, command=self.hist_seleccionar_todo).pack(side="left", padx=5)
            ctk.CTkButton(accion_frame, text="Deseleccionar Todo", fg_color="#9E9E9E", width=140, command=self.hist_deseleccionar_todo).pack(side="left", padx=5)
            ctk.CTkButton(accion_frame, text="Borrar Seleccionados", fg_color="#C62828", width=160, font=("Arial",11,"bold"), command=self.hist_borrar_seleccionados).pack(side="left", padx=15)
        self.cargar_historial()

    def hist_seleccionar_todo(self):
        for var in self.historial_vars.values():
            var.set(True)

    def hist_deseleccionar_todo(self):
        for var in self.historial_vars.values():
            var.set(False)

    def hist_borrar_seleccionados(self):
        if getattr(self, 'historial_es_supervisor', False):
            from tkinter import messagebox
            messagebox.showerror("Sin permiso","Supervisores no pueden borrar historial")
            return
        seleccionados=[id_reg for id_reg,var in self.historial_vars.items() if var.get()]
        if not seleccionados:
            from tkinter import messagebox
            messagebox.showinfo("Borrar", "Tilda los registros que queres borrar")
            return
        from tkinter import messagebox
        if not messagebox.askyesno("Confirmar borrado", f"¿Borrar {len(seleccionados)} registro(s)?"):
            return
        try:
            conn=sqlite3.connect(DB, timeout=15, check_same_thread=False)
            cur=conn.cursor()
            for id_reg in seleccionados:
                cur.execute("DELETE FROM movimientos WHERE id=?", (id_reg,))
            conn.commit()
            conn.close()
            messagebox.showinfo("OK", f"Se borraron {len(seleccionados)} registros")
            self.cargar_historial()
        except Exception as e:
            messagebox.showerror("Error", str(e))


    def hist_imprimir_pdf_seleccionados(self):
        try:
            seleccionados=[id_reg for id_reg,var in self.historial_vars.items() if var.get()]
            if not seleccionados:
                messagebox.showinfo("Imprimir PDF", "Tilda los movimientos que queres imprimir en PDF")
                return
            conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
            datos=[]
            for id_reg in seleccionados:
                cur.execute("SELECT fecha, material_nombre, usuario, cantidad, tipo, destino, motivo, stock_final FROM movimientos WHERE id=?", (id_reg,))
                row=cur.fetchone()
                if row: datos.append(row)
            conn.close()
            if not datos:
                messagebox.showerror("Error","No se encontraron datos"); return
            try:
                from reportlab.pdfgen import canvas
                from reportlab.lib.pagesizes import A4
                path=os.path.join(os.path.expanduser("~"), f"Movimientos_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf")
                os.makedirs("remitos_pdf", exist_ok=True)
                path2=os.path.join("remitos_pdf", os.path.basename(path))
                c=canvas.Canvas(path, pagesize=A4)
                w,h=A4
                c.setFont("Helvetica-Bold", 16)
                c.drawString(40, h-40, "MOVIMIENTOS - PANOL CARILO - OTEADOR")
                c.setFont("Helvetica", 10)

                c.drawString(40, h-70, f"Fecha: {datetime.now().strftime('%d/%m/%Y %H:%M')} - Usuario: {self.usuario['nombre']} - Total: {len(datos)}")
                c.line(40, h-85, w-40, h-85)
                y=h-105
                c.setFont("Helvetica", 9)
                for fecha, mat_nom, usu, cant, tipo, dest, mot, stock_fin in datos:
                    texto=f"{fecha} | {mat_nom} | {tipo} x{cant} | {usu} | Dest:{dest} | Mot:{mot} | Stock:{stock_fin}"
                    if len(texto)>110:
                        c.drawString(40, y, texto[:110]); y-=12
                        c.drawString(40, y, texto[110:220])
                    else: c.drawString(40, y, texto)
                    y-=18
                    if y<60: c.showPage(); y=h-40; c.setFont("Helvetica", 9)
                c.setFont("Helvetica", 9)
                c.drawString(40, 40, f"Ariel Perea - OTEADOR - Movimientos - {datetime.now().strftime('%d/%m/%Y %H:%M')}")
                c.save()
                try: shutil.copy2(path, path2)
                except: pass
                try: os.startfile(path)
                except:
                    import webbrowser; webbrowser.open(path)
                messagebox.showinfo("PDF OK", f"PDF con {len(datos)} movimientos\n{path}")
            except ImportError:
                messagebox.showerror("Error", "Falta reportlab. pip install reportlab")
            except Exception as e:
                messagebox.showerror("Error PDF", str(e))
        except Exception as e:
            messagebox.showerror("Error", str(e))


    def cargar_historial(self):
        if not hasattr(self, 'frame_hist_lista'):
            return
        for w in self.frame_hist_lista.winfo_children(): w.destroy()
        self.historial_vars.clear()
        filtro=self.historial_bus.get().strip().lower() if hasattr(self,'historial_bus') else ""
        tipo_filtro=self.historial_combo_tipo.get() if hasattr(self,'historial_combo_tipo') else "TODOS"
        es_supervisor_hist=getattr(self,'historial_es_supervisor', False)
        try:
            conn=sqlite3.connect(DB, timeout=15, check_same_thread=False)
            cur=conn.cursor()
            cur.execute("CREATE TABLE IF NOT EXISTS movimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, material_id INTEGER, material_nombre TEXT, usuario TEXT, cantidad INTEGER, tipo TEXT, fecha TEXT, destino TEXT, motivo TEXT, stock_final INTEGER)")
            cur.execute("SELECT id,material_id,material_nombre,usuario,cantidad,tipo,fecha,destino,motivo,stock_final FROM movimientos ORDER BY id DESC LIMIT 1000")
            rows=cur.fetchall()
            conn.close()
            # Supervisor no ve Alta/Baja usuarios
            if es_supervisor_hist:
                rows=[r for r in rows if r[5] not in ("ALTA USUARIO","BAJA USUARIO")]
            # Filtro exacto por tipo
            if tipo_filtro!="TODOS":
                rows=[r for r in rows if r[5]==tipo_filtro]
            if filtro:
                rows=[r for r in rows if filtro in str(r).lower()]
            if not rows:
                ctk.CTkLabel(self.frame_hist_lista, text="Sin movimientos con ese filtro", font=("Arial",12)).pack(pady=20)
                return
            cab=ctk.CTkFrame(self.frame_hist_lista, fg_color="#424242"); cab.pack(fill="x", pady=2)
            ctk.CTkLabel(cab, text="V", font=("Arial",10,"bold"), text_color="white", width=30).pack(side="left", padx=5)
            for col,w in [("ID",40),("FECHA/HORA",140),("USUARIO",110),("TIPO",130),("MATERIAL / USUARIO",230),("CANT",50),("STOCK FINAL",80),("DETALLE",280)]:
                ctk.CTkLabel(cab, text=col, font=("Arial",10,"bold"), text_color="white", width=w, anchor="w").pack(side="left", padx=5, pady=5)
            import tkinter as tk
            for id_mov,mat_id,mat_nom,usu,cant,tipo,fecha,dest,motivo,stock_f in rows:
                if "INGRESO NUEVO" in tipo:
                    fg="#E8F5E9"; border="#2E7D32"
                elif tipo=="INGRESO":
                    fg="#F1F8E9"; border="#7CB342"
                elif "RETIRO" in tipo:
                    fg="#FFEBEE"; border="#C62828"
                elif "DEVOLUCION" in tipo:
                    fg="#E3F2FD"; border="#1565C0"
                elif "ALTA USUARIO" in tipo:
                    fg="#FFF3E0"; border="#EF6C00"
                elif "BAJA USUARIO" in tipo:
                    fg="#FCE4EC"; border="#AD1457"
                else:
                    fg="#FFFFFF"; border="#BDBDBD"
                card=ctk.CTkFrame(self.frame_hist_lista, fg_color=fg, border_width=1, border_color=border); card.pack(fill="x", pady=2)
                var=tk.BooleanVar(value=False)
                self.historial_vars[id_mov]=var
                ctk.CTkCheckBox(card, text="", variable=var, width=24, checkbox_width=20, checkbox_height=20).pack(side="left", padx=5)
                ctk.CTkLabel(card, text=f"{id_mov}", font=("Arial",9), width=40, anchor="w").pack(side="left", padx=5, pady=6)
                ctk.CTkLabel(card, text=f"{fecha}", font=("Arial",10), width=140, anchor="w").pack(side="left", padx=5, pady=6)
                ctk.CTkLabel(card, text=f"{usu}", font=("Arial",10,"bold"), width=110, anchor="w").pack(side="left", padx=5)
                ctk.CTkLabel(card, text=f"{tipo}", font=("Arial",10,"bold"), width=130, anchor="w").pack(side="left", padx=5)
                ctk.CTkLabel(card, text=f"{mat_nom}", font=("Arial",10), width=230, anchor="w", wraplength=220).pack(side="left", padx=5)
                ctk.CTkLabel(card, text=f"{cant}", font=("Arial",10,"bold"), width=50).pack(side="left", padx=5)
                ctk.CTkLabel(card, text=f"{stock_f}", font=("Arial",10), width=80).pack(side="left", padx=5)
                detalle=f"{motivo} | {dest}" if dest else f"{motivo}"
                ctk.CTkLabel(card, text=detalle, font=("Arial",9), width=280, anchor="w", wraplength=270, text_color="#424242").pack(side="left", padx=5)
        except Exception as e:
            from tkinter import messagebox
            messagebox.showerror("Error historial", str(e))

    def reparar_historial(self):
        try:
            conn=sqlite3.connect(DB, timeout=15, check_same_thread=False)
            cur=conn.cursor()
            cur.execute("CREATE TABLE IF NOT EXISTS movimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, material_id INTEGER, material_nombre TEXT, usuario TEXT, cantidad INTEGER, tipo TEXT, fecha TEXT, destino TEXT, motivo TEXT, stock_final INTEGER)")
            conn.commit()
            conn.close()
            self.cargar_historial()
            from tkinter import messagebox
            messagebox.showinfo("Historial", "Historial verificado / reparado")
        except Exception as e:
            from tkinter import messagebox
            messagebox.showerror("Error", str(e))

    def vista_historial(self):
        return self.vista_retirados()



    def vista_backup_manual(self):
        for w in self.contenedor.winfo_children(): w.destroy()
        wrapper=ctk.CTkFrame(self.contenedor, fg_color="transparent"); wrapper.pack(fill="both", expand=True, padx=20, pady=10)
        ctk.CTkLabel(wrapper, text="BACKUP MANUAL - PROFESIONAL", font=("Arial",18,"bold")).pack(pady=10)
        ctk.CTkLabel(wrapper, text=f"Carpeta: {CARPETA_BACKUP.resolve()} | Se guardan ultimos 10 backups automaticamente", font=("Arial",10), text_color="gray").pack()

        def ejecutar_backup():
            try:
                ok, path = hacer_backup("MANUAL")
                if ok:
                    # Copias extras a E: y D: por seguridad (como tenias antes)
                    for dest_base in [Path("E:/backups_panol"), Path("D:/backups_panol")]:
                        try:
                            dest_base.mkdir(parents=True, exist_ok=True)
                            shutil.copy2(path, dest_base / Path(path).name)
                        except:
                            pass
                    messagebox.showinfo("Backup OK", f"BACKUP GUARDADO\n{path}")
                    self.vista_backup_manual()  # Refrescar lista
                else:
                    messagebox.showerror("Error Backup", path)
            except Exception as e:
                messagebox.showerror("Error Backup", str(e))

        ctk.CTkButton(wrapper, text="GUARDAR BACKUP AHORA", fg_color="#1565C0", width=300, height=50, font=("Arial",14,"bold"), command=ejecutar_backup).pack(pady=15)

        # --- LISTA PROFESIONAL DE BACKUPS ---
        lista_frame = ctk.CTkScrollableFrame(wrapper, height=350)
        lista_frame.pack(fill="both", expand=True, pady=10)

        backups = sorted(CARPETA_BACKUP.glob("panol_*.db"), key=lambda p: p.stat().st_mtime, reverse=True)
        if not backups:
            ctk.CTkLabel(lista_frame, text="No hay backups aun. Hace el primero con el boton azul.", font=("Arial",11)).pack(pady=20)
        else:
            ctk.CTkLabel(lista_frame, text=f"Ultimos {len(backups)} backups (click en Restaurar para volver a ese estado):", font=("Arial",11,"bold")).pack(pady=5)
            for b in backups:
                row = ctk.CTkFrame(lista_frame, fg_color="#FFFFFF", border_width=1)
                row.pack(fill="x", pady=2, padx=5)
                fecha_mod = datetime.fromtimestamp(b.stat().st_mtime).strftime("%d/%m/%Y %H:%M:%S")
                tam = f"{b.stat().st_size/1024:.1f} KB"
                ctk.CTkLabel(row, text=b.name, font=("Arial",10), width=350, anchor="w").pack(side="left", padx=10)
                ctk.CTkLabel(row, text=f"{fecha_mod} | {tam}", font=("Arial",9), text_color="gray", width=200, anchor="w").pack(side="left", padx=5)

                def hacer_restaurar(ruta=str(b)):
                    if not messagebox.askyesno("Restaurar", f"¿Restaurar este backup?\n{ruta}\n\nSe guarda un backup del estado actual antes."):
                        return
                    ok, msg = restaurar_backup(ruta)
                    if ok:
                        messagebox.showinfo("Restaurado", f"Backup restaurado: {ruta}\nReinicia el programa.")
                    else:
                        messagebox.showerror("Error", msg)

                ctk.CTkButton(row, text="Restaurar", width=80, height=28, fg_color="#FF9800", command=hacer_restaurar).pack(side="right", padx=5)




    def vista_critico(self):
        for w in self.contenedor.winfo_children(): w.destroy()
        wrapper=ctk.CTkFrame(self.contenedor, fg_color="transparent"); wrapper.pack(fill="both", expand=True, padx=10, pady=10)
        ctk.CTkLabel(wrapper, text="MATERIAL CRITICO - STOCK BAJO MINIMO", font=("Arial",14,"bold"), text_color="#C62828").pack(pady=10)
        rol = self.usuario["rol"].lower()
        es_supervisor = "supervisor" in rol
        es_operario = "operario" in rol
        self.critico_vars={}
        self.critico_cant_entries={}
        conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
        try:
            cur.execute("SELECT id,nombre,stock,minimo,marca,ubicacion,usa_minimo FROM materiales WHERE stock <= minimo ORDER BY stock ASC")
        except:
            cur.execute("SELECT id,nombre,stock,minimo,marca,ubicacion,1 FROM materiales WHERE stock <= minimo ORDER BY stock ASC")
        rows=cur.fetchall(); conn.close()
        if not rows:
            ctk.CTkLabel(wrapper, text="No hay materiales en estado critico", font=("Arial",12), text_color="#2E7D32").pack(pady=20)
            return
        def imprimir_seleccionados():
            try:
                seleccionados=[]
                for id_m,var in self.critico_vars.items():
                    if var.get():
                        for r in rows:
                            if r[0]==id_m:
                                cant_entry=self.critico_cant_entries.get(id_m)
                                cant_pedida=cant_entry.get().strip() if cant_entry else "0"
                                if not cant_pedida:
                                    cant_pedida="0"
                                seleccionados.append((r, cant_pedida))
                if not seleccionados:
                    messagebox.showwarning("Nada seleccionado","Seleccione al menos un material"); return
                from reportlab.lib.pagesizes import A4
                from reportlab.pdfgen import canvas
                from reportlab.lib.units import mm
                import os
                fecha=datetime.now().strftime("%d/%m/%Y %H:%M")
                os.makedirs("pdfs_criticos", exist_ok=True)
                pdf_path=os.path.join("pdfs_criticos", f"criticos_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf")
                c=canvas.Canvas(pdf_path, pagesize=A4)
                w,h=A4
                c.setFont("Helvetica-Bold", 14)
                c.drawCentredString(w/2, h-30*mm, "MATERIAL CRITICO - SOLICITUD DE COMPRA")
                c.setFont("Helvetica", 10)
                c.drawCentredString(w/2, h-36*mm, f"Fecha: {fecha} - Usuario: {self.usuario['nombre']} - Items: {len(seleccionados)}")
                c.line(15*mm, h-40*mm, w-15*mm, h-40*mm)
                y=h-48*mm
                c.setFont("Helvetica-Bold", 9)
                x_id=15*mm
                x_material=25*mm
                x_stock=125*mm
                x_cant=150*mm
                c.drawString(x_id, y, "ID")
                c.drawString(x_material, y, "MATERIAL")
                c.drawString(x_stock, y, "STOCK/MIN")
                c.drawString(x_cant, y, "CANT SOLICITADA")
                y-=4*mm
                c.line(10*mm, y, w-10*mm, y)
                y-=6*mm
                for (id_m,nom,stock,minimo,marca,ubi,usa), cant_ped in seleccionados:
                    # Calcular altura necesaria para nombre largo - envolver texto
                    nom_lineas=[]
                    max_chars=70
                    nom_rest=nom
                    while len(nom_rest)>max_chars:
                        nom_lineas.append(nom_rest[:max_chars])
                        nom_rest=nom_rest[max_chars:]
                    nom_lineas.append(nom_rest)
                    alto_necesario=len(nom_lineas)*5*mm
                    if y - alto_necesario < 20*mm:
                        c.showPage()
                        y=h-30*mm
                        c.setFont("Helvetica-Bold", 9)
                        c.drawString(x_id, y, "ID"); c.drawString(x_material, y, "MATERIAL"); c.drawString(x_stock, y, "STOCK/MIN"); c.drawString(x_cant, y, "CANT SOLICITADA")
                        y-=8*mm
                    c.setFont("Helvetica", 9)
                    c.drawString(x_id, y, f"{id_m}")
                    # Dibujar nombre con wrap para que no falte el largo
                    y_temp=y
                    for linea in nom_lineas:
                        c.drawString(x_material, y_temp, linea)
                        y_temp-=5*mm
                    # STOCK y CANT en la primera linea
                    c.drawString(x_stock, y, f"{stock}/{minimo}")
                    c.setFont("Helvetica-Bold", 11)
                    c.drawString(x_cant, y, f"{cant_ped}")
                    c.setFont("Helvetica", 9)
                    y-=max(alto_necesario, 7*mm)
                c.setFont("Helvetica-Oblique", 8)
                c.drawCentredString(w/2, 15*mm, "Generado por Panol Carilo")
                c.save()
                try: os.startfile(pdf_path)
                except: import webbrowser; webbrowser.open(pdf_path)
                messagebox.showinfo("PDF OK", f"PDF con {len(seleccionados)} materiales - {pdf_path}")
            except Exception as e:
                messagebox.showerror("Error PDF", str(e))
        # Botones arriba - supervisor no ve imprimir
        top_btn=ctk.CTkFrame(wrapper, fg_color="transparent"); top_btn.pack(fill="x", pady=5, padx=10)
        if not es_supervisor and not es_operario:
            ctk.CTkButton(top_btn, text="Imprimir PDF Seleccionados PDF", fg_color="#1565C0", width=280, height=36, font=("Arial",12,"bold"), command=imprimir_seleccionados).pack(side="left", padx=5)
        cab=ctk.CTkFrame(wrapper, fg_color="#E0E0E0", border_width=1); cab.pack(fill="x", pady=(10,5), padx=10)
        ctk.CTkLabel(cab, text="✓", font=("Arial",12,"bold"), width=30).pack(side="left", padx=5, pady=6)
        ctk.CTkLabel(cab, text="ID", font=("Arial",12,"bold"), width=40).pack(side="left", padx=5)
        ctk.CTkLabel(cab, text="MATERIAL", font=("Arial",12,"bold"), width=280, anchor="w").pack(side="left", padx=5)
        ctk.CTkLabel(cab, text="STOCK/MIN", font=("Arial",12,"bold"), width=90).pack(side="left", padx=5)
        ctk.CTkLabel(cab, text="UBICACION", font=("Arial",12,"bold"), width=150).pack(side="left", padx=5)
        ctk.CTkLabel(cab, text="CANT SOLICITADA", font=("Arial",12,"bold"), width=150).pack(side="left", padx=5)
        import tkinter as tk
        for id_m,nom,stock,minimo,marca,ubi,usa_min in rows:
            card=ctk.CTkFrame(wrapper, fg_color="#FFCDD2", border_width=1, border_color="#BDBDBD"); card.pack(fill="x", pady=3, padx=10)
            if not es_supervisor and not es_operario:
                var=tk.BooleanVar(value=False)
                self.critico_vars[id_m]=var
                chk=ctk.CTkCheckBox(card, text="", variable=var, width=24, checkbox_width=22, checkbox_height=22); chk.pack(side="left", padx=8, pady=10)
            else:
                ctk.CTkLabel(card, text="!", font=("Arial",12,"bold"), width=24, text_color="#C62828").pack(side="left", padx=8, pady=10)
            ctk.CTkLabel(card, text=f"{id_m}", font=("Arial",11), width=40).pack(side="left", padx=5, pady=10)
            ctk.CTkLabel(card, text=f"{nom}", font=("Arial",12,"bold"), width=260, anchor="w", wraplength=250).pack(side="left", padx=5, pady=10)
            ctk.CTkLabel(card, text=f"{stock}/{minimo}", font=("Arial",12), width=70).pack(side="left", padx=5, pady=10)
            ctk.CTkLabel(card, text=f"{ubi}", font=("Arial",12), width=130, wraplength=120).pack(side="left", padx=5, pady=10)
            if not es_supervisor and not es_operario:
                entry_cant=ctk.CTkEntry(card, width=70, placeholder_text="Ej: 50", font=("Arial",12,"bold"), justify="center"); entry_cant.pack(side="left", padx=10, pady=8)
                self.critico_cant_entries[id_m]=entry_cant
            else:
                ctk.CTkLabel(card, text="Solo lectura", font=("Arial",11), text_color="gray").pack(side="left", padx=10)


    def vista_nuevo(self):
        for w in self.contenedor.winfo_children(): w.destroy()
        wrapper=ctk.CTkFrame(self.contenedor, fg_color="transparent"); wrapper.pack(fill="x", padx=80, pady=20)
        ctk.CTkLabel(wrapper, text="NUEVO MATERIAL - Copia y pega de la web", font=("Arial",16,"bold")).pack(pady=10)
        ctk.CTkLabel(wrapper, text="Podes copiar de Extra Power / cualquier pagina y pegar aca con Ctrl+V o boton Pegar", font=("Arial",11), text_color="gray").pack(pady=(0,10))
        form=ctk.CTkFrame(wrapper, fg_color="#F5F5F5", border_width=1); form.pack(fill="x", padx=20, pady=10)
        # Campos
        ctk.CTkLabel(form, text="Nombre * (copia de web: Tornillo punta mecha etc)", font=("Arial",11,"bold")).pack(anchor="w", padx=10, pady=(10,2))
        # Frame para nombre + boton pegar
        frame_nom=ctk.CTkFrame(form, fg_color="transparent"); frame_nom.pack(fill="x", padx=10, pady=2)
        e_nom=ctk.CTkEntry(frame_nom, placeholder_text="Nombre material - Ej: Tornillo Perfecto dry wafer T1 8X9/16 punta mecha x500", width=400, height=35); e_nom.pack(side="left", padx=(0,10), pady=2)
        def pegar_clipboard():
            try:
                clip = self.clipboard_get()
                if clip:
                    e_nom.delete(0, 'end')
                    e_nom.insert(0, clip.strip())
                    messagebox.showinfo("Pegado", f"Pegado: {clip[:80]}")
            except Exception as e:
                try:
                    import tkinter as tk
                    clip = self.tk.clipboard_get()
                    e_nom.delete(0, 'end')
                    e_nom.insert(0, clip.strip())
                except:
                    messagebox.showwarning("Portapapeles", "Copia primero el texto de la web (Ctrl+C) y luego pega")
        ctk.CTkButton(frame_nom, text="📋 PEGAR", fg_color="#1565C0", width=80, height=32, command=pegar_clipboard).pack(side="left", padx=5)
        # Habilitar Ctrl+V explicitamente
        e_nom.bind("<Control-v>", lambda e: pegar_clipboard())
        e_nom.bind("<Control-V>", lambda e: pegar_clipboard())

        ctk.CTkLabel(form, text="Marca", font=("Arial",11,"bold")).pack(anchor="w", padx=10, pady=(5,2))
        e_marca=ctk.CTkEntry(form, placeholder_text="Marca GENERICA", width=500); e_marca.pack(padx=10, pady=2); e_marca.insert(0,"GENERICA")
        ctk.CTkLabel(form, text="Proveedor", font=("Arial",11,"bold")).pack(anchor="w", padx=10, pady=(5,2))
        e_prov=ctk.CTkEntry(form, placeholder_text="Proveedor", width=500); e_prov.pack(padx=10, pady=2)
        fila=ctk.CTkFrame(form, fg_color="transparent"); fila.pack(fill="x", padx=10, pady=5)
        ctk.CTkLabel(fila, text="Stock *", font=("Arial",11,"bold")).pack(side="left", padx=5)
        e_stock=ctk.CTkEntry(fila, width=100); e_stock.pack(side="left", padx=5); e_stock.insert(0,"0")
        ctk.CTkLabel(fila, text="Minimo *", font=("Arial",11,"bold")).pack(side="left", padx=15)
        e_min=ctk.CTkEntry(fila, width=100); e_min.pack(side="left", padx=5); e_min.insert(0,"1")
        ctk.CTkLabel(fila, text="Ubicacion", font=("Arial",11,"bold")).pack(side="left", padx=15)
        e_ubi=ctk.CTkEntry(fila, width=200); e_ubi.pack(side="left", padx=5); e_ubi.insert(0,"estanteria 1-cajon1-division1")
        ctk.CTkLabel(form, text="Usa minimo? (1=Si, 0=No)", font=("Arial",11,"bold")).pack(anchor="w", padx=10, pady=(5,2))
        e_usa=ctk.CTkEntry(form, width=100); e_usa.pack(anchor="w", padx=10, pady=2); e_usa.insert(0,"1")
        def guardar():
            try:
                nom=e_nom.get().strip(); marca=e_marca.get().strip(); prov=e_prov.get().strip()
                stock=int(e_stock.get()); minimo=int(e_min.get()); ubi=e_ubi.get().strip(); usa=int(e_usa.get())
                if not nom:
                    messagebox.showerror("Error","Nombre obligatorio"); return
                conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
                cur.execute("INSERT INTO materiales (nombre,stock,marca,proveedor,minimo,ubicacion,fecha,usa_minimo) VALUES (?,?,?,?,?,?,?,?)",(nom,stock,marca,prov,minimo,ubi,datetime.now().strftime("%d/%m/%Y"),usa))
                conn.commit(); conn.close()
                messagebox.showinfo("OK", f"Material {nom} creado con Stock {stock}")
                self.cambiar_vista("Inventario")
            except Exception as e:
                messagebox.showerror("Error", str(e))
        ctk.CTkButton(wrapper, text="Guardar Material", fg_color="#2E7D32", width=200, height=40, command=guardar).pack(pady=15)




    def vista_usuarios(self):
        for w in self.contenedor.winfo_children(): w.destroy()
        wrapper=ctk.CTkFrame(self.contenedor, fg_color="transparent"); wrapper.pack(fill="both", expand=True, padx=20, pady=10)
        ctk.CTkLabel(wrapper, text="ALTA USUARIOS", font=("Arial",16,"bold")).pack(pady=10)
        form=ctk.CTkFrame(wrapper, fg_color="white", border_width=1, corner_radius=8); form.pack(fill="x", padx=20, pady=10)

        fila_nom=ctk.CTkFrame(form, fg_color="transparent"); fila_nom.pack(fill="x", padx=20, pady=10)
        ctk.CTkLabel(fila_nom, text="Nombre usuario *", font=("Arial",11,"bold"), width=150, anchor="w").pack(side="left")
        e_nom=ctk.CTkEntry(fila_nom, placeholder_text="Nombre usuario", width=350); e_nom.pack(side="left", padx=10)
        lbl_paso2=ctk.CTkLabel(fila_nom, text="", font=("Arial",11,"bold"), text_color="blue"); lbl_paso2.pack(side="left", padx=20)

        fila_pwd=ctk.CTkFrame(form, fg_color="transparent"); fila_pwd.pack(fill="x", padx=20, pady=10)
        lbl_contr=ctk.CTkLabel(fila_pwd, text="Contraseña *", font=("Arial",11,"bold"), width=150, anchor="w"); lbl_contr.pack(side="left")
        e_pwd=ctk.CTkEntry(fila_pwd, placeholder_text="Contraseña", width=300, show=""); e_pwd.pack(side="left", padx=10)
        btn_cont_nueva_frame=ctk.CTkFrame(fila_pwd, fg_color="transparent")
        lbl_paso3=ctk.CTkLabel(fila_pwd, text="", font=("Arial",11,"bold"), text_color="blue"); lbl_paso3.pack(side="left", padx=10)

        fila_rol=ctk.CTkFrame(form, fg_color="transparent"); fila_rol.pack(fill="x", padx=20, pady=10)
        ctk.CTkLabel(fila_rol, text="Rol *", font=("Arial",11,"bold"), width=150, anchor="w").pack(side="left")
        combo_rol=ctk.CTkComboBox(fila_rol, values=["administrador master","administrador","supervisor","pañolero","operario"], width=350); combo_rol.pack(side="left", padx=10); combo_rol.set("operario")

        self.usuario_a_cambiar = None

        def crear():
            try:
                nom=e_nom.get().strip(); pwd=e_pwd.get().strip(); rol=combo_rol.get().strip()
                if not nom or not pwd:
                    messagebox.showerror("Error","Falta nombre o contraseña"); return
                rol_actual = self.usuario["rol"].lower()
                es_master_actual = "master" in rol_actual
                es_admin_actual = "administrador" in rol_actual
                if not es_master_actual and "master" in rol.lower():
                    messagebox.showerror("PROTEGIDO","Solo MASTER puede crear master"); return
                if es_admin_actual and not es_master_actual and "administrador" in rol.lower():
                    messagebox.showerror("PROTEGIDO","Administrador no puede crear otro administrador - Solo MASTER"); return
                conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
                cur.execute("SELECT id FROM usuarios WHERE nombre=?",(nom,))
                if cur.fetchone():
                    messagebox.showerror("Error", f"Usuario {nom} ya existe - Usa CAMBIAR CONTRASEÑA abajo"); conn.close(); return
                cur.execute("INSERT INTO usuarios (nombre,password,contrasena,rol) VALUES (?,?,?,?)",(nom,pwd,pwd,rol))
                cur.execute("INSERT INTO movimientos (material_id,material_nombre,usuario,cantidad,tipo,fecha,destino,motivo,stock_final) VALUES (?,?,?,?,?,?,?,?,?)",(0, nom, self.usuario["nombre"], 1, "ALTA USUARIO", datetime.now().strftime("%d/%m/%Y %H:%M"), f"Rol:{rol}", f"Alta de usuario {nom}", 0))
                conn.commit(); conn.close()
                messagebox.showinfo("OK", f"Usuario {nom} creado - Rol:{rol}")
                e_nom.delete(0,'end'); e_pwd.delete(0,'end')
                lbl_paso2.configure(text=""); lbl_paso3.configure(text=""); lbl_contr.configure(text="Contraseña *")
                for w in btn_cont_nueva_frame.winfo_children(): w.destroy()
                btn_cont_nueva_frame.pack_forget()
                self.usuario_a_cambiar=None
                self.cargar_lista_usuarios()
            except Exception as e:
                messagebox.showerror("Error", str(e))

        ctk.CTkButton(form, text="Crear Usuario", fg_color="#C62828", width=200, height=35, command=crear).pack(pady=10)

        def hacer_cambiar_contrasena_final():
            if "master" not in self.usuario["rol"].lower():
                messagebox.showerror("PROTEGIDO","Solo MASTER puede cambiar contraseñas"); return
            if not self.usuario_a_cambiar:
                messagebox.showerror("Error","Primero toca CAMBIAR CONTRASEÑA de un usuario de la lista"); return
            nueva = e_pwd.get().strip()
            if not nueva:
                messagebox.showerror("Error","Escribe la contraseña nueva"); return
            id_u, nombre_u = self.usuario_a_cambiar
            try:
                conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
                cur.execute("UPDATE usuarios SET password=?, contrasena=? WHERE id=?", (nueva, nueva, id_u))
                conn.commit(); conn.close()
                messagebox.showinfo("OK", f"Contraseña de {nombre_u} cambiada a {nueva} - Aparece en AZUL abajo (PASO 4)")
                e_nom.delete(0,'end'); e_pwd.delete(0,'end')
                lbl_paso2.configure(text=""); lbl_paso3.configure(text=""); lbl_contr.configure(text="Contraseña *")
                for w in btn_cont_nueva_frame.winfo_children(): w.destroy()
                btn_cont_nueva_frame.pack_forget()
                self.usuario_a_cambiar=None
                self.cargar_lista_usuarios()
            except Exception as e:
                messagebox.showerror("Error", str(e))

        def mostrar_modo_cambio(id_u, nombre_u, rol_u):
            if "master" not in self.usuario["rol"].lower():
                messagebox.showerror("PROTEGIDO","Solo MASTER puede cambiar contraseñas"); return
            self.usuario_a_cambiar = (id_u, nombre_u)
            e_nom.delete(0,'end'); e_nom.insert(0, nombre_u)
            e_pwd.delete(0,'end'); e_pwd.focus()
            lbl_paso2.configure(text=f'PASO 2 -> "{nombre_u}"')
            lbl_paso3.configure(text="PASO 3")
            lbl_contr.configure(text="CONTRASEÑA NUEVA")
            for w in btn_cont_nueva_frame.winfo_children(): w.destroy()
            ctk.CTkButton(btn_cont_nueva_frame, text="CONTRASEÑA NUEVA", fg_color="#1565C0", width=160, height=32, font=("Arial",11,"bold"), command=hacer_cambiar_contrasena_final).pack(side="left", padx=10)
            btn_cont_nueva_frame.pack(side="left", padx=10)
            self.contenedor._parent_canvas.yview_moveto(0)

        self.mostrar_modo_cambio = mostrar_modo_cambio

        # Solo MASTER ve estos carteles (vos Ariel)
        if "master" in self.usuario["rol"].lower():
            ctk.CTkLabel(wrapper, text="--- LISTA DE USUARIOS ---", font=("Arial",12,"bold")).pack(pady=10)
            ctk.CTkLabel(wrapper, text="MASTER: ve todo y cambia contraseñas con CAMBIAR CONTRASEÑA | ADMIN: crea operarios/supervisores pero NO ve ni cambia contraseñas", font=("Arial",10), text_color="#C62828").pack()
        else:
            ctk.CTkLabel(wrapper, text="--- LISTA DE USUARIOS ---", font=("Arial",12,"bold")).pack(pady=10)

        cab=ctk.CTkFrame(wrapper, fg_color="#E3F2FD"); cab.pack(fill="x", padx=10, pady=3)
        ctk.CTkLabel(cab, text="USUARIO", font=("Arial",11,"bold"), width=150, anchor="w").pack(side="left", padx=10)
        if "master" in self.usuario["rol"].lower():
            ctk.CTkLabel(cab, text="CONTRASEÑA", font=("Arial",11,"bold"), text_color="blue", width=120, anchor="w").pack(side="left", padx=10)
        else:
            ctk.CTkLabel(cab, text="CONTRASEÑA", font=("Arial",11,"bold"), text_color="gray", width=120, anchor="w").pack(side="left", padx=10)
        ctk.CTkLabel(cab, text="ROL", font=("Arial",11,"bold"), width=120, anchor="w").pack(side="left", padx=10)
        if "master" in self.usuario["rol"].lower():
            ctk.CTkLabel(cab, text="CAMBIAR CONTRASEÑA", font=("Arial",10,"bold"), text_color="#C62828", width=200, anchor="w").pack(side="left", padx=10)
        ctk.CTkLabel(cab, text="ACCION", font=("Arial",11,"bold"), width=80).pack(side="right", padx=10)

        self.frame_usuarios=ctk.CTkFrame(wrapper); self.frame_usuarios.pack(fill="x", padx=10)
        self.cargar_lista_usuarios()

    def cargar_lista_usuarios(self):
        for w in self.frame_usuarios.winfo_children(): w.destroy()
        conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
        try:
            cur.execute("SELECT id,nombre,contrasena,rol FROM usuarios ORDER BY id ASC")
            rows=cur.fetchall()
        except:
            cur.execute("SELECT id,nombre,password,rol FROM usuarios ORDER BY id ASC")
            rows=cur.fetchall()
        conn.close()
        rol_actual = self.usuario["rol"].lower()
        nombre_actual = self.usuario["nombre"].lower()
        es_master_actual = "master" in rol_actual
        es_admin_actual = "administrador" in rol_actual
        for id_u,nom,pwd,rol in rows:
            rol_lower = rol.lower()
            if not es_master_actual and "master" in rol_lower:
                continue
            if es_admin_actual and not es_master_actual and "administrador" in rol_lower and nom.lower()!=nombre_actual:
                continue
            card=ctk.CTkFrame(self.frame_usuarios, fg_color="#FFFFFF", border_width=1); card.pack(fill="x", pady=2)
            ctk.CTkLabel(card, text=f"{nom}", font=("Arial",11), width=150, anchor="w").pack(side="left", padx=10)
            if es_master_actual:
                ctk.CTkLabel(card, text=f"{pwd}", font=("Arial",11,"bold"), text_color="blue", width=120, anchor="w").pack(side="left", padx=10)
            else:
                ctk.CTkLabel(card, text="****", font=("Arial",11), text_color="gray", width=120, anchor="w").pack(side="left", padx=10)
            ctk.CTkLabel(card, text=f"{rol}", font=("Arial",11), width=120, anchor="w").pack(side="left", padx=10)
            if es_master_actual:
                def cambiar_cb(uid=id_u, nombre=nom, rol_f=rol):
                    self.mostrar_modo_cambio(uid, nombre, rol_f)
                ctk.CTkButton(card, text="CAMBIAR CONTRASEÑA", width=160, height=28, fg_color="#FF9800", font=("Arial",9,"bold"), command=cambiar_cb).pack(side="left", padx=5)
            else:
                ctk.CTkLabel(card, text="Solo MASTER cambia", font=("Arial",9), text_color="gray", width=160).pack(side="left", padx=5)
            def borrar_usuario(uid=id_u, nombre=nom, rol_fila=rol):
                rol_fila_l = rol_fila.lower()
                es_master = "master" in self.usuario["rol"].lower()
                if "master" in rol_fila_l and nombre.lower()!=self.usuario["nombre"].lower():
                    messagebox.showerror("PROTEGIDO", f"MASTER {nombre} solo lo borra el mismo"); return
                if "administrador" in rol_fila_l and not es_master:
                    messagebox.showerror("PROTEGIDO", f"Solo MASTER puede borrar administradores"); return
                if not messagebox.askyesno("Borrar", f"Borrar usuario {nombre}?"): return
                try:
                    conn=sqlite3.connect(DB, timeout=15, check_same_thread=False); cur=conn.cursor()
                    cur.execute("DELETE FROM usuarios WHERE id=?", (uid,))
                    cur.execute("INSERT INTO movimientos (material_id,material_nombre,usuario,cantidad,tipo,fecha,destino,motivo,stock_final) VALUES (?,?,?,?,?,?,?,?,?)",(0, nombre, self.usuario["nombre"], 1, "BAJA USUARIO", datetime.now().strftime("%d/%m/%Y %H:%M"), f"Rol:{rol_fila}", f"Baja de usuario {nombre}", 0))
                    conn.commit(); conn.close()
                    messagebox.showinfo("OK", f"Usuario {nombre} borrado")
                    self.cargar_lista_usuarios()
                except Exception as e:
                    messagebox.showerror("Error", str(e))
            puede_borrar = True
            if "master" in rol_lower and nom.lower()!=nombre_actual:
                puede_borrar=False
            if not es_master_actual and "administrador" in rol_lower:
                puede_borrar=False
            if puede_borrar:
                ctk.CTkButton(card, text="Borrar", width=60, fg_color="#C62828", command=borrar_usuario).pack(side="right", padx=5)
            else:
                ctk.CTkLabel(card, text="Protegido", font=("Arial",9), text_color="gray", width=60).pack(side="right", padx=5)



